            {
              "date": "2026-10-14",
              "broker": "신한투자증권",
              "analyst": "임희연, 이지연",
              "title": "[버크셔 해서웨이 A (NYS:BRK.A)] 에이블 시대, 자본 배분에 시동",
              "summary": "- 2Q26 영업이익 129.8억달러(+16.3%, 이하 YoY) 기록. 제조·서비스·소매 +24.1%, BNSF(철도) +6.3%, BHE(에너지) +26.9%, 고른 성장세 시현- [보험] 언더라이팅 이익 17.3억달러(-13.1%). GEICO(자동차보험사) 합산 비율 91.2%(+7.7%p) 상승을 재보험·원보험이 일부 상쇄. GEICO 수입보 험료는 +1.1%로 성장 둔화 속 사업비율 소폭 14.6% 상승- [비보험] 제조·서비스·소매 44.7억달러(+24.1%). OxyChem 등 인수 효과 로 산업재 매출 +27.3%. BNSF 15.6억달러(+6.3%)는 물동량 +6.5%와 운 임 상승, BHE 8.9억달러(+26.9%)는 유틸리티·파이프라인이 견인. 투자이익 126.8억달러가 반영되며 순이익은 전년 대비 두 배 이상으로 증가",
              "pdfUrl": "https://rreport.einfomax.co.kr/report/eqmemiegczxcllkgcgxeeck.pdf",
              "pages": "5"
            },
            {
              "date": "2025-11-20",
              "broker": "신한투자증권",
              "analyst": "임희연",
              "title": "[버크셔 해서웨이 A (NYS:BRK.A)] 변화의 시작",
              "summary": "- 고성장 테마 과열 완화 및 AI/빅테크 중심 편향된 장세가 정상화되는 국 면에서 시장 대비 아웃 퍼폼 가능성. 최근 구글 신규 편입 및 비중을 상위 10위권까지 확대한 점은 그 동안 기술주에 보수적이던 동사가 기술 섹터 로의 진입을 본격화했다는 신호로 해석됨- [보험 세전이익] 69억달러(+22.2%), 허리케인, 대형 산불 등 자연재해 기 저효과로 보험이익 선방. 게이코 세전이익은 18억달러로 약 11% 감소, 사 고당 손해액 증가 및 보험 모집 관련 비용 집행 영향- 자사주 매입·소각 부재는 현재 주가 수준이 내재가치 대비 크게 저평가되 지 않았다는 경영진의 인식으로 해석됨. 또한, 단기 국채 비중을 지속적으 로 확대하는 흐름은 시장 변동성 확대 가능성을 염두에 둔 보수적 포지셔 닝으로 보임",
              "pdfUrl": "https://rreport.einfomax.co.kr/report/eqxizmgzekezmeegcgxeeck.pdf",
              "pages": "5"
            },
            {
              "date": "2025-11-17",
              "broker": "신한투자증권",
              "analyst": "임희연",
              "title": "[버크셔 해서웨이 A (NYS:BRK.A)] 성장주 편중 장세 속 단기 부진",
              "summary": "- 현실적으로 고성장 테마의 과열이 완화되고 AI/빅테크 중심의 편향된 장 세가 정상화되는 주식시장 환경 조성 시 시장 대비 아웃퍼폼 기대- 동사는 과거 S&P500 지수 대비 10배 이상의 수익률을 기록했으나, 올해 들어 다소 부진한 흐름. 올해 YTD S&P 500 수익률 14.7% vs. BRK 13.1%- 자사주 매입·소각 부재는 동사의 밸류에이션이 적정하거나 높은 밸류에이 션을 부여받고 있다는 경영진의 판단을 시사",
              "pdfUrl": "https://rreport.einfomax.co.kr/report/eqxiiizzkmieqikgcgxeeck.pdf",
              "pages": "4"
            }
